const int TOTAL_STEPS = sizeof(song) / sizeof(song);
const unsigned long STEP_TIME_MS = 112;

unsigned long halfPeriodLead = 0, halfPeriodHarm = 0, halfPeriodBass = 0;
unsigned long lastToggleLead = 0, lastToggleHarm = 0, lastToggleBass = 0;
bool stateLead = false, stateHarm = false, stateBass = false;

void setup() {
  pinMode(PIN_LEAD, OUTPUT);
  pinMode(PIN_HARM, OUTPUT);
  pinMode(PIN_BASS, OUTPUT);
}

void playPolyphonicStep(uint16_t fLead, uint16_t fHarm, uint16_t fBass, unsigned long durationMs) {
  halfPeriodLead = (fLead > 0) ? (500000UL / fLead) : 0;
  halfPeriodHarm = (fHarm > 0) ? (500000UL / fHarm) : 0;
  halfPeriodBass = (fBass > 0) ? (500000UL / fBass) : 0;

  unsigned long startTime = millis();
  unsigned long muteLeadTime = durationMs - 12;

  while (millis() - startTime < durationMs) {
    unsigned long now = micros();
    unsigned long elapsed = millis() - startTime;

    if (halfPeriodLead > 0 && elapsed < muteLeadTime) {
      if (now - lastToggleLead >= halfPeriodLead) {
        lastToggleLead = now;
        stateLead = !stateLead;
        digitalWrite(PIN_LEAD, stateLead);
      }
    } else {
      digitalWrite(PIN_LEAD, LOW);
    }

    if (halfPeriodHarm > 0) {
      if (now - lastToggleHarm >= halfPeriodHarm) {
        lastToggleHarm = now;
        stateHarm = !stateHarm;
        digitalWrite(PIN_HARM, stateHarm);
      }
    } else {
      digitalWrite(PIN_HARM, LOW);
    }

    if (halfPeriodBass > 0) {
      if (now - lastToggleBass >= halfPeriodBass) {
        lastToggleBass = now;
        stateBass = !stateBass;
        digitalWrite(PIN_BASS, stateBass);
      }
    } else {
      digitalWrite(PIN_BASS, LOW);
    }
  }
}

void loop() {
  for (int i = 0; i < TOTAL_STEPS; i++) {
    unsigned long stepDuration = song[i].duration * STEP_TIME_MS;
    playPolyphonicStep(song[i].lead, song[i].harm, song[i].bass, stepDuration);
  }

  digitalWrite(PIN_LEAD, LOW);
  digitalWrite(PIN_HARM, LOW);
  digitalWrite(PIN_BASS, LOW);
  delay(3000);
}
